```python
import math

def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Check if 2023 is a prime number
year = 2023
if is_prime(year):
    print(f"{year} is a prime number.")
else:
    print(f"{year} is not a prime number.")
